import json

# Load report data
with open('output/report_data.json', 'r') as f:
    data = json.load(f)

# Load chart SVGs
charts = {}
for key in ['monthly_trends', 'quarterly_comparison', 'top_products', 'top_stores', 
            'discount_impact', 'customer_segments', 'seasonality']:
    with open(f'output/chart_{key}.svg', 'r') as f:
        charts[key] = f.read()

# Format numbers
def fmt_currency(val):
    return f"${val:,.2f}"

def fmt_pct(val):
    return f"{val:.2f}%"

def fmt_number(val):
    return f"{val:,.0f}"

kpi = data['kpi']
yoy = data['yoy']
cust = data['customer_insights']

# Build HTML report
html = f'''<!DOCTYPE html>
<html lang="en">
