<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Chocolate Retail Sales Performance Report (2023–2024)</title>
<style>
  :root {{
    --primary: #5D4037;
    --secondary: #8D6E63;
    --accent: #D84315;
    --success: #2E7D32;
    --warning: #F9A825;
    --info: #1565C0;
    --light: #EFEBE9;
    --text: #3E2723;
    --muted: #A1887F;
    --bg: #FAFAFA;
    --card: #FFFFFF;
    --border: #D7CCC8;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
