    border: 1px solid var(--border);
    transition: transform 0.2s;
  }}
  .kpi-card:hover {{ transform: translateY(-2px); }}
  .kpi-card .value {{
    font-size: 1.8rem;
    font-weight: 700;
    color: var(--primary);
